import{_ as t,o,c as a,a2 as s}from"./chunks/framework.Cdp8-jB6.js";const m=JSON.parse('{"title":"Sensory feedback — cue vocabulary (taste definition)","description":"","frontmatter":{},"headers":[],"relativePath":"wip/sensory-cue-vocabulary.md","filePath":"wip/sensory-cue-vocabulary.md"}'),r={name:"wip/sensory-cue-vocabulary.md"};function n(i,e,c,l,d,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="sensory-feedback-—-cue-vocabulary-taste-definition" tabindex="-1">Sensory feedback — cue vocabulary (taste definition) <a class="header-anchor" href="#sensory-feedback-—-cue-vocabulary-taste-definition" aria-label="Permalink to &quot;Sensory feedback — cue vocabulary (taste definition)&quot;">​</a></h1><p><em>Draft for Marko&#39;s review. Defines how the sensory layer&#39;s <strong>discrete event cues</strong> feel — the sound each one makes, when it&#39;s allowed to fire, and what must stay silent. Once you&#39;ve marked this up, I sweep <code>cue()</code> across the routes from it. This is the &quot;80% of the feel&quot; tier (sound everywhere + haptic on mobile); the two continuous hero sonifications (/fly velocity, /explore Kepler) are separate.</em></p><hr><h2 id="principles-the-feel-we-re-aiming-for" tabindex="-1">Principles (the feel we&#39;re aiming for) <a class="header-anchor" href="#principles-the-feel-we-re-aiming-for" aria-label="Permalink to &quot;Principles (the feel we&#39;re aiming for)&quot;">​</a></h2><ol><li><strong>Confirm, don&#39;t announce.</strong> A cue acknowledges <em>your</em> action landed — it&#39;s the click of the brass gear, not a notification. It never volunteers information.</li><li><strong>Musical, not mechanical.</strong> Tones sit on a small consonant palette (A4 / C5 / G5) so they read as intentional, never as a system beep. The one exception is <code>warning</code>, which is <em>meant</em> to be rough.</li><li><strong>Quiet by default.</strong> Peak gain ≤0.14 (≈ well under speech). You should feel the layer more than notice it. It ducks to near-silence under narration.</li><li><strong>One action, one cue.</strong> Debounced selection fires once. No double-taps, no stacking.</li><li><strong>Sound is universal; touch is the bonus.</strong> Every cue plays a tone on <em>all</em> platforms — desktop is the audio-first experience, not second-class. Mobile layers a haptic pulse on top (the two senses confirm each other).</li><li><strong>Only user-initiated, discrete moments.</strong> Never on hover, scroll, camera drag/zoom/tilt, passive animation, autoplay, route navigation, or programmatic state (deep-link focus, restore). Pointer-move events stay silent by rule (they drive lightweight state only — the render-storm lesson).</li><li><strong>Respect the body.</strong> Reduced-motion removes haptics (and gyro); an active screen reader mutes the tones (voice owns the audio channel).</li></ol><hr><h2 id="the-five-cues" tabindex="-1">The five cues <a class="header-anchor" href="#the-five-cues" aria-label="Permalink to &quot;The five cues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cue</th><th>Means</th><th>Sound</th><th>Haptic (mobile)</th></tr></thead><tbody><tr><td><strong>select</strong></td><td>&quot;you picked this&quot;</td><td>soft sine <strong>660 Hz</strong>, 80 ms</td><td>light</td></tr><tr><td><strong>confirm</strong></td><td>&quot;that completed&quot;</td><td>rising two-note <strong>C5→G5</strong> (523→784 Hz), 180 ms</td><td>success</td></tr><tr><td><strong>threshold</strong></td><td>&quot;a boundary was crossed&quot;</td><td>triangle <strong>440 Hz</strong> (A4), 120 ms</td><td>medium</td></tr><tr><td><strong>warning</strong></td><td>&quot;caution / limit hit&quot;</td><td>rough sawtooth <strong>220 Hz</strong>, 200 ms</td><td>warning</td></tr></tbody></table><p><em>(Dropped <code>back</code> — panel dismiss stays silent, per review: &quot;we don&#39;t want to overdo it.&quot;)</em></p><h3 id="where-each-fires-the-sweep-map" tabindex="-1">Where each fires (the sweep map) <a class="header-anchor" href="#where-each-fires-the-sweep-map" aria-label="Permalink to &quot;Where each fires (the sweep map)&quot;">​</a></h3><ul><li><strong>select</strong> — tapping any object that focuses/opens a detail. <strong>Wired across:</strong><code>/explore</code> (planet · sun · small body · satellite · belt) · <code>/earth</code> <code>/moon</code><code>/mars</code> (surface site + orbital object, canvas + index list) · <code>/earth</code> <code>/mars</code> (orbital-regime pick) · <code>/missions</code> (card) · <code>/fleet</code> (spacecraft) · <code>/iss</code><code>/tiangong</code> (module + ship) · <code>/fly</code> (jump to a mission event). All at true user-click seams; deep-link / tour / restore paths stay silent.</li></ul><h3 id="⚠-confirm-threshold-warning-—-no-natural-triggers-today" tabindex="-1">⚠ confirm / threshold / warning — no natural triggers today <a class="header-anchor" href="#⚠-confirm-threshold-warning-—-no-natural-triggers-today" aria-label="Permalink to &quot;⚠ confirm / threshold / warning — no natural triggers today&quot;">​</a></h3><p>Reality check from the sweep: the current app is <strong>selection-driven</strong>. The <code>confirm</code> (solver-complete) · <code>threshold</code> (mission arc crossing an orbit) · <code>warning</code> (Δv over budget · fuel exhausted) moments were designed for an <em>interactive-solver</em> <code>/fly</code> that was never built — today&#39;s <code>/fly</code> is a cinematic playback (no fuel/Δv model, no solver, no user-facing crossing events). Rather than invent features to hang cues on, these three stay <strong>defined but unwired</strong>. They&#39;re ready for: (a) any future interactive feature that genuinely completes / warns, and (b) the Phase-4 hero sonifications, which mark real physical moments. <code>select</code> is the primary wired cue.</p><hr><h2 id="what-must-stay-silent-restraint-list" tabindex="-1">What must stay SILENT (restraint list) <a class="header-anchor" href="#what-must-stay-silent-restraint-list" aria-label="Permalink to &quot;What must stay SILENT (restraint list)&quot;">​</a></h2><p>Hover / focus · scroll · camera drag / zoom / <strong>tilt (gyro)</strong> · pinch · the tab strip <em>inside</em> a panel (too chatty) · route-to-route navigation · settings toggles (including the sensory toggles themselves) · autoplay / sim-time ticks · any programmatic selection (deep-link <code>?id=</code>, session restore). When in doubt: silent.</p><hr><h2 id="mix-timing" tabindex="-1">Mix &amp; timing <a class="header-anchor" href="#mix-timing" aria-label="Permalink to &quot;Mix &amp; timing&quot;">​</a></h2><ul><li>Peak gain ≤ 0.14 linear; chords share one envelope (no click transients).</li><li>Ducks to 0.02 gain within ~50 ms when narration plays; restores over ~200 ms.</li><li>Cue tones are ≤ 200 ms — a punctuation mark, never a phrase.</li><li>Haptic kinds map to Capacitor&#39;s coarse styles (light/medium/heavy impact + success/warning notification); web Android uses short <code>navigator.vibrate</code> patterns; iOS-web + desktop have no haptic (tone only).</li></ul><hr><h2 id="review-outcome-locked-2026-07-11" tabindex="-1">Review outcome (locked 2026-07-11) <a class="header-anchor" href="#review-outcome-locked-2026-07-11" aria-label="Permalink to &quot;Review outcome (locked 2026-07-11)&quot;">​</a></h2><ol><li><strong>In-panel tab switches</strong> — <strong>silent</strong>. ✓</li><li><strong>Panel close / <code>back</code></strong> — <strong>silent</strong>; the <code>back</code> cue is dropped entirely (&quot;we don&#39;t want to overdo it&quot;). Only the <em>open</em> side (<code>select</code>) sounds.</li><li><strong>Volume</strong> — <strong>keep 0.14</strong> peak.</li><li><strong>Interaction mapping</strong> — good start; proceed with the sweep and iterate from real use. No launch/play-control cues for now.</li></ol><p>→ Sweeping <code>cue()</code> across the routes to this spec.</p>',23)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
